//! PostgreSQL application-owned schema, never derived from imported database SQL.
// C collation preserves SQLite's bytewise string comparison. All stored integer
// values use BIGINT; source records remain lossless opaque BYTEA values.
pub(crate) const INTAKE: &[&str] = &[
    "CREATE TABLE IF NOT EXISTS intake_jobs (id TEXT COLLATE \"C\" PRIMARY KEY, kind TEXT COLLATE \"C\" NOT NULL, state TEXT COLLATE \"C\" NOT NULL, total BIGINT NOT NULL, budget BIGINT NOT NULL, max_files BIGINT NOT NULL, encoded_limit BIGINT NOT NULL, zip_complete BIGINT NOT NULL DEFAULT 0, completed BIGINT NOT NULL DEFAULT 0, files BIGINT NOT NULL DEFAULT 0, path_bytes BIGINT NOT NULL DEFAULT 0, reserved BIGINT NOT NULL, error TEXT COLLATE \"C\")",
    "CREATE TABLE IF NOT EXISTS intake_sources (job TEXT COLLATE \"C\" NOT NULL REFERENCES intake_jobs(id), path TEXT COLLATE \"C\" NOT NULL, canonical TEXT COLLATE \"C\" NOT NULL, digest TEXT COLLATE \"C\" NOT NULL, length BIGINT NOT NULL, PRIMARY KEY(job,path), UNIQUE(job,canonical))",
];

pub(crate) const CATALOG: &[&str] = &[
    "CREATE TABLE IF NOT EXISTS catalog_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fingerprint TEXT COLLATE \"C\" NOT NULL UNIQUE, source_job TEXT COLLATE \"C\" NOT NULL REFERENCES intake_jobs(id), library_uuid TEXT COLLATE \"C\", state TEXT COLLATE \"C\" NOT NULL, reason TEXT COLLATE \"C\", conflict BIGINT NOT NULL DEFAULT 0)",
    "CREATE TABLE IF NOT EXISTS catalog_sources(version BIGINT NOT NULL REFERENCES catalog_versions(id), job TEXT COLLATE \"C\" NOT NULL, path TEXT COLLATE \"C\" NOT NULL, digest TEXT COLLATE \"C\" NOT NULL, length BIGINT NOT NULL, PRIMARY KEY(version,path), FOREIGN KEY(job,path) REFERENCES intake_sources(job,path))",
    "CREATE TABLE IF NOT EXISTS catalog_records(version BIGINT NOT NULL REFERENCES catalog_versions(id), kind TEXT COLLATE \"C\" NOT NULL, ordinal BIGINT NOT NULL, original BYTEA NOT NULL, PRIMARY KEY(version,kind,ordinal))",
    "CREATE TABLE IF NOT EXISTS catalog_pictures(version BIGINT NOT NULL REFERENCES catalog_versions(id), uuid TEXT COLLATE \"C\" NOT NULL, bin_uuid TEXT COLLATE \"C\" NOT NULL, event_uuid TEXT COLLATE \"C\" NOT NULL, name BYTEA NOT NULL, caption BYTEA NOT NULL, rating BIGINT NOT NULL, flag_status BIGINT NOT NULL, name_display TEXT COLLATE \"C\" NOT NULL, name_fold BYTEA NOT NULL, name_bytes BIGINT NOT NULL, caption_display TEXT COLLATE \"C\" NOT NULL, caption_fold BYTEA NOT NULL, caption_bytes BIGINT NOT NULL, PRIMARY KEY(version,uuid))",
    "CREATE TABLE IF NOT EXISTS catalog_albums(version BIGINT NOT NULL REFERENCES catalog_versions(id), uuid TEXT COLLATE \"C\" NOT NULL, name BYTEA NOT NULL, sort_order BIGINT NOT NULL, name_display TEXT COLLATE \"C\" NOT NULL, name_fold BYTEA NOT NULL, name_bytes BIGINT NOT NULL, PRIMARY KEY(version,uuid))",
    "CREATE TABLE IF NOT EXISTS catalog_memberships(version BIGINT NOT NULL, album_uuid TEXT COLLATE \"C\" NOT NULL, picture_uuid TEXT COLLATE \"C\" NOT NULL, picture_index BIGINT NOT NULL, PRIMARY KEY(version,album_uuid,picture_uuid), UNIQUE(version,album_uuid,picture_index), FOREIGN KEY(version,album_uuid) REFERENCES catalog_albums(version,uuid), FOREIGN KEY(version,picture_uuid) REFERENCES catalog_pictures(version,uuid))",
    "CREATE TABLE IF NOT EXISTS catalog_item_errors(version BIGINT NOT NULL REFERENCES catalog_versions(id), picture_uuid TEXT COLLATE \"C\" NOT NULL, code TEXT COLLATE \"C\" NOT NULL, PRIMARY KEY(version,picture_uuid,code))",
];

pub(crate) const API: &[&str] = &[
    "CREATE TABLE IF NOT EXISTS api_ids(id TEXT COLLATE \"C\" PRIMARY KEY,kind TEXT COLLATE \"C\" NOT NULL,version BIGINT NOT NULL REFERENCES catalog_versions(id),source_key TEXT COLLATE \"C\" NOT NULL,UNIQUE(kind,version,source_key))",
    "CREATE TABLE IF NOT EXISTS api_imports(job TEXT COLLATE \"C\" PRIMARY KEY REFERENCES intake_jobs(id),version BIGINT NOT NULL REFERENCES catalog_versions(id))",
    "CREATE INDEX IF NOT EXISTS api_ids_lookup ON api_ids(kind,version,source_key)",
    "CREATE TABLE IF NOT EXISTS api_adaptation_errors(job TEXT COLLATE \"C\" PRIMARY KEY REFERENCES intake_jobs(id),code TEXT COLLATE \"C\" NOT NULL)",
];

pub(crate) const EXPORT: &[&str] = &[
    "CREATE TABLE IF NOT EXISTS export_jobs(id TEXT COLLATE \"C\" PRIMARY KEY,kind TEXT COLLATE \"C\" NOT NULL,state TEXT COLLATE \"C\" NOT NULL,completed BIGINT NOT NULL DEFAULT 0,total BIGINT NOT NULL DEFAULT 0,reserved BIGINT NOT NULL DEFAULT 0,retained BIGINT NOT NULL DEFAULT 0,error TEXT COLLATE \"C\",recipe TEXT COLLATE \"C\")",
];
